// Zoomable Area Chart — Interaction, route: ref
// Source: zoomable-area-chart
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useEffect, useId, useMemo, useRef } from 'react';
import * as d3 from 'd3';

// ---- inlined from zoomableArea ----
type FlightDay = { date: Date; count: number };

const DAYS = 731; // 2000-01-01 through 2001-12-31
const SHOCK_DAY = 619; // index of 2001-09-11

/** mulberry32: a fixed seed keeps the series identical across reloads. */
function seededRandom(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const random = seededRandom(20010911);

/** Three days of near-total grounding, then an exponential recovery that never quite closes. */
function shockFactor(day: number): number {
  const since = day - SHOCK_DAY;
  if (since < 0) return 1;
  if (since < 3) return 0.02;
  return 1 - 0.45 * Math.exp(-(since - 3) / 28);
}

/** Synthetic daily flight counts: weekly rhythm, summer peak, and the September 2001 collapse. */
const flightsPerDay: FlightDay[] = Array.from({ length: DAYS }, (_, day) => {
  const date = new Date(Date.UTC(2000, 0, 1 + day));
  const weekday = date.getUTCDay();
  const weekly = weekday === 6 ? 0.82 : weekday === 0 ? 0.94 : 1;
  const seasonal = 1 + 0.09 * Math.sin((2 * Math.PI * (day - 60)) / 365.25);
  const noise = 1 + (random() - 0.5) * 0.05;
  return { date, count: Math.round(12000 * weekly * seasonal * shockFactor(day) * noise) };
});

const MARGIN = { top: 16, right: 20, bottom: 32, left: 56 };

/** One row per day, in date order; the x domain is the extent of `date`. */
export type Data = { date: Date; count: number }[];

export default function ZoomableAreaChart({
  data = flightsPerDay,
  width
}: {
  data?: Data;
  width: number;
}) {
  const svgRef = useRef<SVGSVGElement | null>(null);
  const clipId = `clip${useId().replace(/:/g, '')}`;
  const height = Math.round(width * 0.5);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  const x = useMemo(
    () =>
      d3
        .scaleUtc()
        .domain(d3.extent(data, (d) => d.date) as [Date, Date])
        .range([MARGIN.left, MARGIN.left + innerWidth]),
    [data, innerWidth]
  );

  const y = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain([0, d3.max(data, (d) => d.count) ?? 0])
        .nice()
        .range([MARGIN.top + innerHeight, MARGIN.top]),
    [data, innerHeight]
  );

  // Rebuilt per zoom event against the rescaled x, which is what redraws the area.
  const areaPath = useMemo(
    () => (xz: d3.ScaleTime<number, number>) =>
      d3
        .area<FlightDay>()
        .curve(d3.curveStepAfter)
        .x((d) => xz(d.date))
        .y0(y(0))
        .y1((d) => y(d.count))(data) ?? '',
    [data, y]
  );

  useEffect(() => {
    const node = svgRef.current;
    if (!node || width === 0) return;

    const svg = d3.select(node);
    svg.selectAll('*').remove();

    svg
      .append('clipPath')
      .attr('id', clipId)
      .append('rect')
      .attr('x', MARGIN.left)
      .attr('y', MARGIN.top)
      .attr('width', innerWidth)
      .attr('height', innerHeight);

    const path = svg
      .append('path')
      .attr('clip-path', `url(#${clipId})`)
      .attr('fill', 'var(--accent)')
      .attr('fill-opacity', 0.75)
      .attr('d', areaPath(x));

    const gx = svg
      .append('g')
      .attr('class', 'axis')
      .attr('transform', `translate(0,${MARGIN.top + innerHeight})`);

    const drawXAxis = (scale: d3.ScaleTime<number, number>) => {
      gx.call(d3.axisBottom(scale).ticks(innerWidth / 90).tickSizeOuter(0)).call((g) =>
        g.select('.domain').attr('stroke', 'var(--line)')
      );
    };
    drawXAxis(x);

    svg
      .append('g')
      .attr('class', 'axis')
      .attr('transform', `translate(${MARGIN.left},0)`)
      .call(d3.axisLeft(y).ticks(5).tickSize(-innerWidth).tickFormat(d3.format('.2s')))
      .call((g) => g.select('.domain').remove())
      .call((g) => g.selectAll('.tick line').attr('class', 'grid'));

    svg
      .append('text')
      .attr('class', 'axis')
      .attr('x', MARGIN.left)
      .attr('y', MARGIN.top - 4)
      .text('Flights per day. Scroll or drag to zoom.');

    // scaleExtent caps depth; translateExtent pins panning to the data's own domain, so the
    // chart cannot be dragged off itself. Both are in x only, leaving y fixed.
    const zoom = d3
      .zoom<SVGSVGElement, unknown>()
      .scaleExtent([1, 32])
      .extent([
        [MARGIN.left, 0],
        [MARGIN.left + innerWidth, height]
      ])
      .translateExtent([
        [MARGIN.left, -Infinity],
        [MARGIN.left + innerWidth, Infinity]
      ])
      .on('zoom', (event: d3.D3ZoomEvent<SVGSVGElement, unknown>) => {
        const xz = event.transform.rescaleX(x);
        path.attr('d', areaPath(xz));
        drawXAxis(xz);
      });

    svg.call(zoom);

    return () => {
      svg.on('.zoom', null);
      svg.selectAll('*').remove();
    };
  }, [width, height, innerWidth, innerHeight, x, y, areaPath, clipId]);

  if (width === 0) return null;

  return (
    <svg
      ref={svgRef}
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      style={{ cursor: 'grab', touchAction: 'none' }}
      role="img"
      aria-label="Zoomable area chart of daily US flights from 2000 through 2001"
    />
  );
}
